import operator
import re
import sys

_TOKEN_RE = re.compile(r"\d+|[A-Z]\d+|[A-Z]+|<>|<=|>=|[-+*/(),:<>=]")
_CELL_RE = re.compile(r"[A-Z]\d+")
_CMP = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}
_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"


def _tokenize(text):
    return _TOKEN_RE.findall("".join(text.split()))


def _parse(tokens):
    pos = 0

    def take():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def at(tok):
        return pos < len(tokens) and tokens[pos] == tok

    def expr():
        node = term()
        while at("+") or at("-"):
            op = take()
            node = ("bin", op, node, term())
        return node

    def term():
        node = unary()
        while at("*") or at("/"):
            op = take()
            node = ("bin", op, node, unary())
        return node

    def unary():
        if at("-"):
            take()
            return ("neg", unary())
        return atom()

    def atom():
        tok = take()
        if tok.isdigit():
            return ("num", int(tok))
        if tok == "(":
            node = expr()
            take()  # ")"
            return node
        if _CELL_RE.fullmatch(tok):
            return ("ref", tok)
        take()  # "("
        if tok == "IF":
            left = expr()
            op = take()
            right = expr()
            take()  # ","
            then = expr()
            take()  # ","
            other = expr()
            take()  # ")"
            return ("if", op, left, right, then, other)
        args = []
        while True:
            if (pos + 1 < len(tokens) and _CELL_RE.fullmatch(tokens[pos])
                    and tokens[pos + 1] == ":"):
                first = take()
                take()  # ":"
                args.append(("range", first, take()))
            else:
                args.append(expr())
            if not at(","):
                break
            take()  # ","
        take()  # ")"
        return ("call", tok, args)

    return expr()


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 1 << 20))
    memo: dict[str, int | str] = {}
    busy: set[str] = set()

    def range_names(first, last):
        c1, r1 = ord(first[0]), int(first[1:])
        c2, r2 = ord(last[0]), int(last[1:])
        names = []
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                name = chr(c) + str(r)
                if name in cells:
                    names.append(name)
        return names

    def value_of(name):
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in busy:
            return _CYCLE
        text = cells[name].strip()
        if not text.startswith("="):
            memo[name] = int(text)
            return memo[name]
        busy.add(name)
        result = evaluate(_parse(_tokenize(text[1:])))
        busy.discard(name)
        memo[name] = result
        return result

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return value_of(node[1])
        if kind == "neg":
            v = evaluate(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return _DIV0
            quotient = abs(left) // abs(right)
            return quotient if (left < 0) == (right < 0) else -quotient
        if kind == "if":
            _, op, left_node, right_node, then_node, else_node = node
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            return evaluate(then_node if _CMP[op](left, right) else else_node)
        # Function call: SUM, MIN, MAX
        values = []
        for arg in node[2]:
            if arg[0] == "range":
                for name in range_names(arg[1], arg[2]):
                    v = value_of(name)
                    if isinstance(v, str):
                        return v
                    values.append(v)
            else:
                v = evaluate(arg)
                if isinstance(v, str):
                    return v
                values.append(v)
        if node[1] == "SUM":
            return sum(values)
        if not values:
            return 0
        return min(values) if node[1] == "MIN" else max(values)

    return {name: value_of(name) for name in cells}
